const fs = require('fs');

const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
const a = BigInt(input[0] || 0);
const c = BigInt(input[1] || 0);

const x = [];
const y = [];

let currentA = a;
let currentC = c;

while (currentA !== 0n || currentC !== 0n) {
    x.push(Number(currentA % 3n));
    currentA /= 3n;
    y.push(Number(currentC % 3n));
    currentC /= 3n;
}

let b = 0n;
for (let i = x.length - 1; i >= 0; i--) {
    const digit = (y[i] - x[i] + 3) % 3;
    b = b * 3n + BigInt(digit);
}

console.log(b.toString());

